data.query:
query Query($where: IntegrationWhereInput, $whereM: IntegrationModelWhereInput) {
  integration(where: $where, first:1) {
    edges { node {
      id
      name
      active
      configurationData
      integrationModels(where:$whereM, first:1) {
        edges {node {
          id
          inboundFlowId
          name
          lastTransactionAt
          order
        }}
      }
    }}
  }
}

